// Package passwords builds the grouped credentials view from the module files.
// It replaces .devcontainer/password.sh (#881): the module files remain the
// source, .password is a regenerated, private view of them.
package passwords

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
)

const header = "# devzone : identifiers of the accounts created by devzone. Plain-text secrets:\n" +
	"# never commit, copy or paste them into a ticket. Regenerated by devzone.\n" +
	"# service\taddress\tuser\tpassword\n"

// Path returns the grouped credentials file of the devzone folder.
func Path(root string) string {
	return filepath.Join(root, ".password")
}

// Regenerate rebuilds .password from the workspace folders, silently on
// success. The file is removed when no account is left. The replacement is
// atomic and the file is created with mode 600; no secret is logged or passed
// to another process.
func Regenerate(root string) error {
	if root == "" {
		return errors.New("devzone folder unavailable")
	}
	entries := collect(root)
	target := Path(root)
	if len(entries) == 0 {
		err := os.Remove(target)
		if err != nil && !os.IsNotExist(err) {
			return err
		}
		return nil
	}
	sortEntries(entries)
	var data bytes.Buffer
	data.WriteString(header)
	for _, entry := range entries {
		data.WriteString(entry)
		data.WriteByte('\n')
	}
	return writeAtomic(target, data.Bytes())
}
